/* Compiles the driver's own bc_decode_task + fast paths (bcband_extracted.h, generated by
 * genbcband.py from vn_droiddeck_bc.c) and checks the band split end to end: it replicates
 * bc_decode_cmd's task split, runs each task through the real bc_decode_task, and compares the
 * assembled image byte-for-byte with a whole-image decode.
 *
 * This is the check the earlier ones were missing: bcfast.c tested the decoders without bands,
 * bcsplit.c tested the bands without the fast paths, so a fast path that ignored the band offset
 * passed both and still wrote the top rows of every band. That shipped as a texture whose lower
 * half was never decoded ("the map is cut in half"). See run.sh. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
/* The extracted structs name two Vulkan types; the test needs no other Vulkan header. */
typedef uint64_t VkDeviceSize;
typedef uint64_t VkBuffer;
#include "util/format/u_format.h"
#include "util/u_math.h"
#include "bcband_extracted.h"


static uint32_t rng_state = 12345;
static uint32_t rnd(void) { rng_state = rng_state * 1103515245u + 12345u; return rng_state >> 8; }

struct case_ {
   enum pipe_format src_fmt, dst_fmt;
   uint32_t width, height, slices;
   const char *name;
};

/* Replicates bc_decode_cmd: same rows_per_slice, same y0/height, same task fields. */
static int
check(const struct case_ *c, unsigned threads)
{
   const unsigned src_row = (c->width / 4) * util_format_get_blocksize(c->src_fmt);
   const unsigned dst_row = c->width * util_format_get_blocksize(c->dst_fmt);
   const size_t src_slice = (size_t)src_row * (c->height / 4);
   const size_t dst_slice = (size_t)dst_row * c->height;
   const size_t src_bytes = src_slice * c->slices;
   const size_t dst_bytes = dst_slice * c->slices;

   uint8_t *src = malloc(src_bytes), *want = malloc(dst_bytes), *got = malloc(dst_bytes);
   for (size_t i = 0; i < src_bytes; i++) src[i] = rnd();
   memset(want, 0xAB, dst_bytes); memset(got, 0xAB, dst_bytes);

   struct vn_dd_bc_job job = {
      .src_format = c->src_fmt, .dst_format = c->dst_fmt,
      .width = c->width, .height = c->height, .slices = c->slices,
      .src_row = src_row, .src_slice = src_slice,
      .dst_row = dst_row, .dst_slice = dst_slice,
   };

   /* Reference: one whole-slice decode per slice, the way the pre-split code did it. */
   for (uint32_t s = 0; s < c->slices; s++)
      util_format_translate(c->dst_fmt, want + s * dst_slice, dst_row, 0, 0,
                            c->src_fmt, src + s * src_slice, src_row, 0, 0,
                            c->width, c->height);

   /* The split, exactly as bc_decode_cmd computes it (n_jobs=1 here): only a single-slice job
    * is split into bands. */
   const unsigned target = threads * 4;
   unsigned rows_per_slice = c->height;
   if (1 < target && c->slices == 1 && c->height > 4) {
      rows_per_slice = (c->height / DIV_ROUND_UP(target, 1) / 4) * 4;
      if (!rows_per_slice) rows_per_slice = c->height;
   }
   unsigned n = 0;
   for (uint32_t s = 0; s < c->slices; s++) {
      for (uint32_t y = 0; y < c->height; y += rows_per_slice) {
         const uint32_t h = MIN2(rows_per_slice, c->height - y);
         struct vn_dd_bc_task t = { .job = job, .src = src + s * src_slice,
                                    .dst = got + s * dst_slice, .y0 = y, .height = h };
         bc_decode_task(&t, NULL, 0);   /* the real function from the driver */
         n++;
      }
   }

   int bad = memcmp(want, got, dst_bytes) != 0;
   if (bad) {
      size_t first = 0;
      while (first < dst_bytes && want[first] == got[first]) first++;
      printf("  MISMATCH %-16s %ux%ux%u threads=%u bands=%u  first diff at byte %zu (row %zu)\n",
             c->name, c->width, c->height, c->slices, threads, n, first, first / dst_row);
   }
   free(src); free(want); free(got);
   return bad;
}

int main(void)
{
   struct case_ cases[] = {
      { PIPE_FORMAT_DXT1_RGB,  PIPE_FORMAT_R8G8B8A8_UNORM, 256, 256, 1, "BC1_RGB" },
      { PIPE_FORMAT_DXT1_RGBA, PIPE_FORMAT_R8G8B8A8_UNORM, 256, 256, 1, "BC1_RGBA" },
      { PIPE_FORMAT_DXT3_RGBA, PIPE_FORMAT_R8G8B8A8_UNORM, 256, 256, 1, "BC2" },
      { PIPE_FORMAT_DXT5_RGBA, PIPE_FORMAT_R8G8B8A8_UNORM, 256, 256, 1, "BC3" },
      { PIPE_FORMAT_RGTC1_UNORM, PIPE_FORMAT_R8_UNORM,     256, 256, 1, "BC4" },
      { PIPE_FORMAT_RGTC2_UNORM, PIPE_FORMAT_R8G8_UNORM,   256, 256, 1, "BC5" },
      { PIPE_FORMAT_RGTC1_SNORM, PIPE_FORMAT_R8_SNORM,     256, 256, 1, "BC4_SNORM" },
      { PIPE_FORMAT_RGTC2_SNORM, PIPE_FORMAT_R8G8_SNORM,   256, 256, 1, "BC5_SNORM" },
      { PIPE_FORMAT_DXT5_RGBA, PIPE_FORMAT_R8G8B8A8_UNORM, 128,  64, 1, "BC3_128x64" },
      { PIPE_FORMAT_DXT1_RGB,  PIPE_FORMAT_R8G8B8A8_UNORM,  64, 128, 1, "BC1_64x128" },
      { PIPE_FORMAT_DXT5_RGBA, PIPE_FORMAT_R8G8B8A8_UNORM,   4, 512, 1, "BC3_4x512" },
      { PIPE_FORMAT_RGTC2_UNORM, PIPE_FORMAT_R8G8_UNORM,   512,   4, 1, "BC5_512x4" },
      /* Slices: an array/cubemap upload is not band-split, but it goes through the same
       * per-slice task loop, so it is worth covering too. */
      { PIPE_FORMAT_DXT5_RGBA, PIPE_FORMAT_R8G8B8A8_UNORM, 128, 128, 6, "BC3_128x128x6" },
      { PIPE_FORMAT_DXT1_RGB,  PIPE_FORMAT_R8G8B8A8_UNORM, 256, 256, 4, "BC1_256x256x4" },
      { PIPE_FORMAT_RGTC2_UNORM, PIPE_FORMAT_R8G8_UNORM,   256, 256, 3, "BC5_256x256x3" },
   };
   const unsigned thread_counts[] = { 1, 2, 4, 8, 16 };
   int fail = 0, total = 0;
   for (unsigned t = 0; t < sizeof(thread_counts)/sizeof(*thread_counts); t++) {
      for (unsigned i = 0; i < sizeof(cases)/sizeof(*cases); i++) {
         total++;
         fail += check(&cases[i], thread_counts[t]);
      }
   }
   printf("%s: %d/%d cases exact (fast path + band split, real driver code)\n",
          fail ? "FAIL" : "PASS", total - fail, total);
   return fail != 0;
}
